"""
CKD Lab Data Unit Harmonization Script

This script handles:
1. Removing rows with missing values
2. Converting comma decimals to period decimals
3. Converting scientific notation to normal format
4. Harmonizing units to US conventional units
5. Rounding all values to 2 decimal places
"""

import pandas as pd
import numpy as np
import re

