def clean_value(val):
    """Convert a value string to float, handling comma decimals and scientific notation."""
    if pd.isna(val):
        return np.nan

    val_str = str(val).strip()

    if val_str == '' or val_str.lower() == 'nan':
        return np.nan

    # Replace comma with period for decimal separator
    # But be careful: if there's already a period, comma might be thousands separator
    # In this data, comma seems to be decimal separator (European format)
    val_str = val_str.replace(',', '.')

    # Handle potential double periods from replacement
    val_str = re.sub(r'\.+', '.', val_str)

    try:
        # This handles scientific notation automatically
        return float(val_str)
    except ValueError:
        return np.nan


def harmonize_value(value, col_name, ref_info):
    """Harmonize a single value based on expected ranges and conversion factors."""
    if pd.isna(value):
        return np.nan

    normal_min, normal_max = ref_info['normal_range']

    # Check if value is within normal range
    if normal_min <= value <= normal_max:
        return value

    # Check if conversion is available
    if ref_info.get('alt_conversion') and ref_info.get('alt_range'):
        alt_min, alt_max = ref_info['alt_range']
        alt_conv = ref_info['alt_conversion']

        # Check if value falls in alternative unit range (outside normal but in alt range)
        if alt_min <= value <= alt_max:
            # Convert from alternative unit to standard unit
            converted = value * alt_conv
            # Verify converted value is now in normal range
            if normal_min <= converted <= normal_max:
                return converted

        # If value is outside normal range and above the alt range max,
        # it's likely in the alt unit - try conversion
        if value > normal_max:
            converted = value * alt_conv
            if normal_min <= converted <= normal_max:
                return converted

        # If value is below normal range but not in alt range,
        # try the conversion anyway for edge cases
        if value < normal_min:
            converted = value * alt_conv
            if normal_min <= converted <= normal_max:
                return converted

    # Return original value if no conversion needed/applicable
    return value


def process_data(input_path, output_path):
    """Main function to process and harmonize the CKD lab data."""
    print(f"Reading data from {input_path}...")

    # Read CSV
    df = pd.read_csv(input_path)
    print(f"Original data shape: {df.shape}")

    # Get lab columns (all except patient_id)
    lab_columns = [col for col in df.columns if col != 'patient_id']

    # Step 1: Clean all values (handle comma decimals, scientific notation)
    print("Cleaning values (comma decimals, scientific notation)...")
    for col in lab_columns:
        df[col] = df[col].apply(clean_value)

    # Step 2: Remove rows with any missing values
    print("Removing rows with missing values...")
    original_count = len(df)
    df = df.dropna()
    removed_count = original_count - len(df)
    print(f"Removed {removed_count} rows with missing values. Remaining: {len(df)}")

    # Step 3: Harmonize units
    print("Harmonizing units...")
    for col in lab_columns:
        if col in LAB_REFERENCE:
            ref_info = LAB_REFERENCE[col]
            df[col] = df[col].apply(lambda x: harmonize_value(x, col, ref_info))
        # If column not in reference, keep as-is

    # Step 4: Round all numeric values to 2 decimal places
    print("Rounding values to 2 decimal places...")
    for col in lab_columns:
        df[col] = df[col].apply(lambda x: round(x, 2) if pd.notna(x) else x)

    # Step 5: Format output - ensure proper decimal format (X.XX)
    print("Formatting output...")

    # Convert to string with 2 decimal places for lab columns
    for col in lab_columns:
        df[col] = df[col].apply(lambda x: f"{x:.2f}" if pd.notna(x) else '')

    # Keep patient_id as integer
    df['patient_id'] = df['patient_id'].astype(int)

    # Save to output
